float posterize(float f, float steps) {
    return floor(f*steps) / steps;
}

float cbrt(float f) {
    return pow(f, 1./3.);
}

vec3 rgb_to_oklab(vec3 c) {
	float l = 0.4122214708 * c.r + 0.5363325363 * c.g + 0.0514459929 * c.b;
	float m = 0.2119034982 * c.r + 0.6806995451 * c.g + 0.1073969566 * c.b;
	float s = 0.0883024619 * c.r + 0.2817188376 * c.g + 0.6299787005 * c.b;

    float l_ = cbrt(l);
    float m_ = cbrt(m);
    float s_ = cbrt(s);

    vec3 res;
	res.x = 0.2104542553*l_ + 0.7936177850*m_ - 0.0040720468*s_;
	res.y = 1.9779984951*l_ - 2.4285922050*m_ + 0.4505937099*s_;
	res.z = 0.0259040371*l_ + 0.7827717662*m_ - 0.8086757660*s_;

	return res;
}

vec3 oklab_to_rgb(vec3 color) {
	float l_ = color.x + 0.3963377774 * color.y + 0.2158037573 * color.z;
    float m_ = color.x - 0.1055613458 * color.y - 0.0638541728 * color.z;
    float s_ = color.x - 0.0894841775 * color.y - 1.2914855480 * color.z;

    float l = l_*l_*l_;
    float m = m_*m_*m_;
    float s = s_*s_*s_;

    vec3 res;
	res.r =  4.0767416621 * l - 3.3077115913 * m + 0.2309699292 * s;
	res.g = -1.2684380046 * l + 2.6097574011 * m - 0.3413193965 * s;
	res.b = -0.0041960863 * l - 0.7034186147 * m + 1.7076147010 * s;

    return res;
}

vec3 rgb(int r, int g, int b) {
    return vec3(float(r) / 255., float(g) / 255., float(b) / 255.);
}


void mainImage( out vec4 fragColor, in vec2 fragCoord )
{
    vec2 uv = fragCoord/iResolution.xy;

    vec3 start  = rgb_to_oklab( vec3(0.501, 0    , 0.501) );
    vec3 end    = rgb_to_oklab( rgb(255,215,0) );

    float f = 1. - uv.y;

    f = posterize(f, 6.);

    vec3 col = mix(start, end, f);

    col = oklab_to_rgb(col);

    fragColor = vec4(col,1.0);
}

